# Parameters (empty text = NULL, as in the T-SQL procedure)
dbutils.widgets.text("snapshot_month", "")  # T-SQL type: DATE

snapshot_month = dbutils.widgets.get("snapshot_month") or None

# COMMAND ----------

# MAGIC %md
# MAGIC ### Step 1: delete dbo.inventory_snapshots (T-SQL line 37)

# COMMAND ----------

spark.sql(r"""
DELETE FROM dbo.inventory_snapshots
WHERE
  snapshot_month = LAST_DAY(TO_DATE(CAST(:snapshot_month AS DATE)))
""", args={"snapshot_month": snapshot_month})

# COMMAND ----------

# MAGIC %md
# MAGIC ### Step 2: insert dbo.inventory_snapshots (T-SQL line 40)
# MAGIC Rewrites applied: transient_table_to_cte.

# COMMAND ----------

spark.sql(r"""
WITH tmp_movements AS (
  SELECT
    m.site_id,
    m.product_id,
    SUM(CASE WHEN m.movement_type = 'RECEIPT' THEN m.quantity ELSE 0 END) AS received_qty,
    SUM(CASE WHEN m.movement_type = 'DISPENSE' THEN m.quantity ELSE 0 END) AS dispensed_qty,
    SUM(CASE WHEN m.movement_type IN ('ADJUSTMENT', 'RETURN') THEN m.quantity ELSE 0 END) AS adjusted_qty
  FROM dbo.inventory_movements AS m
  WHERE
    m.movement_date BETWEEN MAKE_DATE(
      YEAR(CAST(:snapshot_month AS DATE)),
      MONTH(CAST(:snapshot_month AS DATE)),
      1
    ) AND LAST_DAY(TO_DATE(CAST(:snapshot_month AS DATE)))
  GROUP BY
    m.site_id,
    m.product_id
)
INSERT INTO dbo.inventory_snapshots (
  snapshot_month,
  site_id,
  product_id,
  opening_qty,
  received_qty,
  dispensed_qty,
  adjusted_qty,
  closing_qty,
  avg_dispensed_3m,
  loaded_at
)
SELECT
  LAST_DAY(TO_DATE(CAST(:snapshot_month AS DATE))),
  COALESCE(mv.site_id, prev.site_id),
  COALESCE(mv.product_id, prev.product_id),
  COALESCE(prev.closing_qty, 0),
  COALESCE(mv.received_qty, 0),
  COALESCE(mv.dispensed_qty, 0),
  COALESCE(mv.adjusted_qty, 0),
  COALESCE(prev.closing_qty, 0) + COALESCE(mv.received_qty, 0) - COALESCE(mv.dispensed_qty, 0) + COALESCE(mv.adjusted_qty, 0),
  NULL,
  CURRENT_TIMESTAMP()
FROM tmp_movements AS mv
FULL OUTER JOIN (
  SELECT
    site_id,
    product_id,
    closing_qty
  FROM dbo.inventory_snapshots
  WHERE
    snapshot_month = LAST_DAY(DATEADD(MONTH, -1, TO_DATE(CAST(:snapshot_month AS DATE))))
) AS prev
  ON prev.site_id = mv.site_id AND prev.product_id = mv.product_id
""", args={"snapshot_month": snapshot_month})

# COMMAND ----------

# MAGIC %md
# MAGIC ### Step 3: update dbo.inventory_snapshots (T-SQL line 66)
# MAGIC Rewrites applied: update_from_to_merge.

# COMMAND ----------

spark.sql(r"""
WITH trend AS (
  SELECT
    site_id,
    product_id,
    snapshot_month,
    AVG(dispensed_qty) OVER (
      PARTITION BY site_id, product_id
      ORDER BY snapshot_month
      ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
    ) AS avg_dispensed_3m
  FROM dbo.inventory_snapshots
  WHERE
    snapshot_month BETWEEN LAST_DAY(DATE_ADD(MONTH, -2, TO_DATE(CAST(:snapshot_month AS DATE)))) AND LAST_DAY(TO_DATE(CAST(:snapshot_month AS DATE)))
)
MERGE INTO dbo.inventory_snapshots AS s
USING trend AS t
ON t.site_id = s.site_id
AND t.product_id = s.product_id
AND t.snapshot_month = s.snapshot_month
WHEN MATCHED AND s.snapshot_month = LAST_DAY(TO_DATE(CAST(:snapshot_month AS DATE))) THEN UPDATE SET
  s.avg_dispensed_3m = t.avg_dispensed_3m
""", args={"snapshot_month": snapshot_month})

